description:
Shipping cost depends on the parcel and where it goes. The records are defined for you. Write `public static class Shipping` with `public static decimal Cost(Parcel p)` as **one** `switch` expression using property, relational and logical patterns:

- weight 0 or less, or any side 0 or less: throw `ArgumentException`;
- letters (see below) to any country: 1.20;
- the UK: up to 2 kg 3.50, up to 10 kg 7.00, more 15.00;
- the EU (`Destination.Region == "EU"`): up to 2 kg 8.00, more 20.00;
- anywhere else: up to 2 kg 12.00, more 30.00;
- `Express` doubles the price (letters cannot be express: an express letter is priced as a parcel).

A letter is `{ Weight: <= 0.1, Size.Depth: <= 1 }`.

starter.Solution.cs:
public static class Shipping
{
    public static decimal Cost(Parcel p) => 3.50m;
}

solution.Solution.cs:
public static class Shipping
{
    public static decimal Cost(Parcel p)
    {
        decimal basePrice = p switch
        {
            { Weight: <= 0 } or { Size.Width: <= 0 } or { Size.Height: <= 0 } or { Size.Depth: <= 0 }
                => throw new ArgumentException("bad parcel"),
            { Weight: <= 0.1, Size.Depth: <= 1, Express: false } => 1.20m,
            { To.Country: "UK", Weight: <= 2 } => 3.50m,
            { To.Country: "UK", Weight: <= 10 } => 7.00m,
            { To.Country: "UK" } => 15.00m,
            { To.Region: "EU", Weight: <= 2 } => 8.00m,
            { To.Region: "EU" } => 20.00m,
            { Weight: <= 2 } => 12.00m,
            _ => 30.00m,
        };
        return p.Express ? basePrice * 2 : basePrice;
    }
}

unitTests:
Parcel P(double kg, string country, string region, bool express = false, double depth = 10) =>
    new(kg, new Size(20, 20, depth), new Destination(country, region), express);

Test("letters", () =>
{
    CheckEq(Shipping.Cost(P(0.05, "US", "NA", depth: 0.5)), 1.20m);
    CheckEq(Shipping.Cost(P(0.05, "UK", "UK", express: true, depth: 0.5)), 7.00m);
});

Test("the UK by weight", () =>
{
    CheckEq(Shipping.Cost(P(2, "UK", "UK")), 3.50m);
    CheckEq(Shipping.Cost(P(9.9, "UK", "UK")), 7.00m);
    CheckEq(Shipping.Cost(P(12, "UK", "UK")), 15.00m);
});

Test("EU and the rest", () =>
{
    CheckEq(Shipping.Cost(P(1, "FR", "EU")), 8.00m);
    CheckEq(Shipping.Cost(P(3, "DE", "EU")), 20.00m);
    CheckEq(Shipping.Cost(P(1, "JP", "AS")), 12.00m);
    CheckEq(Shipping.Cost(P(5, "JP", "AS", express: true)), 60.00m);
});

Test("bad parcels", () =>
{
    CheckThrows<ArgumentException>(() => Shipping.Cost(P(0, "UK", "UK")));
    CheckThrows<ArgumentException>(() => Shipping.Cost(P(1, "UK", "UK", depth: 0)));
});

